package org.brightstats.model;
import java.util.*;
import java.nio.file.*;
import com.google.gson.*;
import org.brightstats.model.TypedDiagram.*;
import org.brightstats.stats.*;
public final class DiagramSemProductChecks {
    private static int checks;
    private static void require(boolean value,String label){checks++;if(!value)throw new AssertionError(label);}
    public static void main(String[] args)throws Exception{List<String> names=java.util.stream.IntStream.range(0,9).mapToObj(i->"V"+i).toList();double[][] data=new double[240][9];Random random=new Random(1957);for(var row:data){double x=random.nextGaussian(),z=.3*x+Math.sqrt(.91)*random.nextGaussian(),y=.6*x+.4*z+.4*(x*z-.3)+.5*random.nextGaussian();double[] values={x,z,y};for(int i=0;i<3;i++)for(int j=0;j<3;j++)row[3*i+j]=values[i]+.25*random.nextGaussian();}var blocks=List.of(new PlsSem.Block("X",new int[]{0,1,2},PlsSem.Mode.A),new PlsSem.Block("Z",new int[]{3,4,5},PlsSem.Mode.A),new PlsSem.Block("Y",new int[]{6,7,8},PlsSem.Mode.A));var model=SemModel.reflective(names,data,blocks,List.of(new PlsSem.Edge(0,2)),true,false).model();var document=DiagramTemplates.sem(model,false);var factors=document.nodes().stream().filter(node->node.type()==ElementType.CBSEM_LATENT_VARIABLE).toList();var main=document.links().stream().filter(link->link.type()==ElementType.CBSEM_CONNECTION_BETWEEN_LV_AND_LV).findFirst().orElseThrow();JsonObject properties=new JsonObject();properties.addProperty("edge",main.id());document=document.with(new Node("anchor",ElementType.DONGLE,"",0,0,properties)).with(new Link("moderation",ElementType.CBSEM_CONNECTION_FOR_MODERATION,factors.get(1).id(),"anchor",new JsonObject()));var root=document.node(document.root());var rootProperties=root.properties();JsonArray probes=new JsonArray();for(int value=-1;value<=1;value++){var probe=new JsonObject();probe.addProperty("name","Z="+value);var values=new JsonObject();values.addProperty(factors.get(1).id(),value);probe.add("values",values);probes.add(probe);}rootProperties.add("moderationProbes",probes);document=document.with(new Node(root.id(),root.type(),root.label(),root.x(),root.y(),rootProperties));var before=document.json();var compiled=DiagramSemProducts.compile(document,names,data,false);require(document.json().equals(before),"Compilation leaves the editable graph unchanged");require(compiled.addedMainPaths()==1,"Missing lower-order path added");require(compiled.specification().indicatorBlocks().size()==2,"Explicit reflective membership");require(compiled.specification().probes().size()==3,"Stable node identities map to centered probes");var options=new CovarianceSem.Options(1200,1e-8,1e-12,CovarianceSem.Likelihood.NORMAL,false,.95,CovarianceSem.Information.EXPECTED);var fit=SemProductIndicators.fit(data,compiled.specification(),options);require(fit.covariance().converged()&&fit.covariance().identified(),"Compiled product model fits");require(fit.conditional().size()==6,"Conditional slopes include both interaction factors");JsonObject fixed=new JsonObject();fixed.addProperty("free",false);fixed.addProperty("value",0);var constrained=document.with(new Link("fixed_zero",ElementType.CBSEM_CONNECTION_BETWEEN_LV_AND_LV,factors.get(1).id(),factors.get(2).id(),fixed));var retained=DiagramSemProducts.compile(constrained,names,data,false);require(retained.addedMainPaths()==0,"Explicit fixed-zero main path preserved");int z=retained.identities().get(factors.get(1).id()),y=retained.identities().get(factors.get(2).id());require(retained.specification().base().parameters().stream().flatMap(parameter->parameter.locations().stream()).noneMatch(location->location.kind()==SemModel.Kind.DIRECTED&&location.row()==y&&location.column()==z),"Fixed zero not freed by hierarchy");var coefficient=new JsonObject();coefficient.addProperty("free",true);coefficient.addProperty("value",.25);coefficient.addProperty("equality","interaction_group");coefficient.addProperty("lower",.1);coefficient.addProperty("upper",.9);var bound=document.with(new Link("moderation",ElementType.CBSEM_CONNECTION_FOR_MODERATION,factors.get(1).id(),"anchor",coefficient));var request=DiagramSemProducts.compile(bound,names,data,false).specification().interactions().getFirst();require(request.coefficient().equality().equals("interaction_group")&&request.coefficient().lower()==.1&&request.coefficient().upper()==.9,"Interaction constraints compiled");var output=Path.of(args[0]);Files.createDirectories(output);var gson=new GsonBuilder().serializeSpecialFloatingPointValues().create();JsonObject item=new JsonObject();item.add("diagram",document.json());item.add("observations",gson.toJsonTree(data));item.add("compiled",gson.toJsonTree(compiled));item.add("fit",gson.toJsonTree(fit));Files.writeString(output.resolve("compiled.json"),gson.toJson(item));System.out.println("{\"checks\":"+checks+",\"interactions\":1}");}
}
